def count_words_slow(words):
    counts = {}
    for i in range(len(words)):
        w = words[i]
        found = False
        for j in range(len(words)):
            if words[j] == w:
                if w in counts:
                    counts[w] += 1
                else:
                    counts[w] = 1
                found = True
                break
    return counts

words = ['apple', 'banana', 'apple', 'cherry']
print(count_words_slow(words))

